25	using namespace tir;
26	
27	static Buffer makeBufferWithLayout(const Buffer &buffer, const Layout &layout,
28	                                   Map<Var, Var> &var_remap) {
29	  const auto *ptr_type =
30	      TVM_TYPE_AS(buffer->data->type_annotation, PointerTypeNode);
31	  Type new_type;
32	  Var new_var;
33	  // convert fragments to normal local buffer
34	  if (ptr_type->storage_scope == "local.fragment") {
35	    new_type = PointerType(ptr_type->element_type, "local");
36	    new_var = Var(buffer->data->name_hint, new_type);
37	  } else {
38	    new_var = buffer->data;
39	  }
40	  if (ptr_type->storage_scope == "global") {
41	    new_var = buffer->data;
42	  } else {
43	    if (var_remap.count(buffer->data)) {
44	      new_var = var_remap[buffer->data];
45	    } else {
46	      var_remap.Set(buffer->data, new_var);
47	    }
48	  }
49	  Array<PrimExpr> layout_shape = layout->OutputShape();
50	  Array<PrimExpr> output_shape = layout_shape;
51	
52	  if (ptr_type->storage_scope == "shared" ||
53	      ptr_type->storage_scope == "shared.ub" ||
54	      ptr_type->storage_scope == "shared.l1") {
55	    int replicate_extent = 1;
56	    Array<PrimExpr> buffer_shape = buffer->shape;
57	    int buffer_extent = 1;
58	    int layout_extent = 1;
59	    for (size_t i = 0; i < buffer_shape.size(); i++) {
60	      auto shape = buffer_shape[i].as<IntImmNode>();
61	      buffer_extent *= shape->value;
62	    }
63	    for (size_t i = 0; i < layout_shape.size(); i++) {
64	      auto shape = layout_shape[i].as<IntImmNode>();
65	      layout_extent *= shape->value;
66	    }
67	    replicate_extent = buffer_extent / layout_extent;
68	    if (replicate_extent > 1) {
69	      output_shape.insert(output_shape.begin(), replicate_extent);
70	    }
71	  }
72	  return Buffer(new_var, buffer->dtype, output_shape, {}, buffer->elem_offset,
73	                buffer->name, buffer->data_alignment, buffer->offset_factor,
74	                buffer->buffer_type);
75	}
76	
77	/*!
78	 * \brief A class that rewrites buffer references in a statement based on a
79	 * given buffer remapping.
80	 *
81	 * This class is used to update buffer references in a statement after buffer
82	 * transformations have been applied. It specifically handles the remapping of
83	 * padding annotations.
84	 */
85	class RemapBufferRewriter : public arith::IRMutatorWithAnalyzer {
86	public:
87	  /*!
88	   * \brief Substitute buffer references in a statement based on a given buffer
89	   * remapping. \param stmt The statement to rewrite. \param buffer_remap A map
90	   * from old buffers to new buffers. \return The rewritten statement.
91	   */
92	  static Stmt Substitute(Stmt stmt, Map<Buffer, Buffer> buffer_remap) {
93	    arith::Analyzer analyzer;
94	    RemapBufferRewriter substituter(&analyzer);
95	    substituter.buffer_remap_ = std::move(buffer_remap);
96	    return substituter.VisitStmt(stmt);
97	  }
98	
99	private:
100	  using arith::IRMutatorWithAnalyzer::IRMutatorWithAnalyzer;
101	
102	  Stmt VisitStmt_(const BlockNode *op) final {
103	    if (op->annotations.count(attr::kPaddingMap)) {
104	      return RewritePaddingMap(op);
105	    }
106	    return IRMutatorWithAnalyzer::VisitStmt_(op);
107	  }
108	
109	  /*!
110	   * \brief Rewrite the padding map annotation of a block.
111	   * \param op The block node to rewrite.
112	   * \return The rewritten block.
113	   */
114	  Stmt RewritePaddingMap(const BlockNode *op) {
115	    auto padding_map =
116	        op->annotations.Get(attr::kPaddingMap).as<Map<Var, PrimExpr>>().value();
117	
118	    Map<Var, Var> var_remap = CreateVarRemap();
119	    Map<Var, PrimExpr> new_padding_map =
120	        RemapPaddingMap(padding_map, var_remap);
121	
122	    auto block = Downcast<Block>(IRMutatorWithAnalyzer::VisitStmt_(op));
123	    auto block_ptr = block.CopyOnWrite();
124	    block_ptr->annotations.Set(attr::kPaddingMap, new_padding_map);
125	    return block;
126	  }
127	
128	  /*!
129	   * \brief Create a mapping from old variables to new variables based on buffer
130	   * remapping. \return A map from old variables to new variables.
131	   */
132	  Map<Var, Var> CreateVarRemap() const {
133	    Map<Var, Var> var_remap;
134	    for (const auto &[buffer, buffer_remap] : buffer_remap_) {
135	      var_remap.Set(buffer->data, buffer_remap->data);
136	    }
137	    return var_remap;
138	  }
139	
140	  /*!
141	   * \brief Remap the padding map using the variable remapping.
142	   * \param padding_map The original padding map.
143	   * \param var_remap The variable remapping.
144	   * \return The remapped padding map.
145	   */
146	  Map<Var, PrimExpr> RemapPaddingMap(const Map<Var, PrimExpr> &padding_map,
147	                                     const Map<Var, Var> &var_remap) const {
148	    Map<Var, PrimExpr> new_padding_map;
149	    for (const auto &[var, padding] : padding_map) {
150	      if (var_remap.count(var)) {
151	        new_padding_map.Set(var_remap.at(var), padding);
152	      } else {
153	        new_padding_map.Set(var, padding);
154	      }
155	    }
156	    return new_padding_map;
157	  }
158	
159	  Map<Buffer, Buffer> buffer_remap_;
160	};
161	
162	class LowerTileOpPass : arith::IRMutatorWithAnalyzer {
163	public:
164	  static PrimFunc Substitute(PrimFunc f) {
165	    arith::Analyzer analyzer;
166	    LowerTileOpPass substituter(&analyzer);
167	    // Trace the buffer map for tvm_access_ptr
168	    substituter.buffer_map_.insert(f->buffer_map.begin(), f->buffer_map.end());
169	    for (const auto &[_, buffer] : f->buffer_map) {
170	      substituter.buffer_data_to_buffer_.Set(buffer->data, buffer);
171	    }
172	    auto target = f->GetAttr<Target>(tvm::attr::kTarget);
173	    ICHECK(target.defined()) << "LowerTileOpPass: Require the target attribute";
174	    substituter.target_ = target.value();
175	    PrimFuncNode *fptr = f.CopyOnWrite();
176	    fptr->body = substituter.VisitStmt(f->body);
177	    fptr->body =
178	        RemapBufferRewriter::Substitute(fptr->body, substituter.buffer_remap_);
179	    return f;
180	  }
181	
182	private:
183	  using arith::IRMutatorWithAnalyzer::IRMutatorWithAnalyzer;
184	
185	  Stmt VisitStmt_(const BlockNode *op) final {
186	    // Record the mapping from buffer data var to buffer for later lookup
187	    for (auto buffer : op->alloc_buffers) {
188	      buffer_map_.insert({buffer->data, buffer});
189	    }
190	    for (auto match_buffer : op->match_buffers) {
191	      buffer_map_.insert({match_buffer->buffer->data, match_buffer->buffer});
192	    }
193	    for (auto buffer : op->alloc_buffers) {
194	      buffer_data_to_buffer_.Set(buffer->data, buffer);
195	    }
196	    Map<Var, Layout> vmap;
197	    if (op->annotations.count(attr::kLayoutMap)) {
198	      auto layout_map = op->annotations.at(attr::kLayoutMap)
199	                            .as<Map<Buffer, Layout>>()
200	                            .value();
201	      for (auto [buffer, layout] : layout_map) {
202	        buffer_remap_.Set(buffer,
203	                          makeBufferWithLayout(buffer, layout, var_remap_));
204	        layout_map_.Set(buffer, layout);
205	      }
206	    }
207	    auto block = Downcast<Block>(arith::IRMutatorWithAnalyzer::VisitStmt_(op));
208	    auto block_ptr = block.CopyOnWrite();
209	    for (size_t i = 0; i < block->alloc_buffers.size(); i++) {
210	      auto buffer = block->alloc_buffers[i];
211	      if (buffer_remap_.count(buffer)) {
212	        block_ptr->alloc_buffers.Set(i, buffer_remap_[buffer]);
213	      }
214	    }
215	    for (const auto &buffer : workspaces_)
216	      block_ptr->alloc_buffers.push_back(buffer);
217	    workspaces_.clear();
218	    block_ptr->annotations.erase(attr::kLayoutMap);
219	    return block;
220	  }
221	
222	  int CheckAndGetBufferRowSize(Buffer buffer) {
223	    CHECK(buffer->shape.size() >= 2)
224	        << "The dimension of Buffer \"" << buffer->name << "\" with shape "
225	        << buffer->shape << " should be at least 2";
226	
227	    auto dim = buffer->shape.size();
228	    auto buffer_row_size = buffer->shape[dim - 1].as<IntImmNode>()->value;
229	    return buffer_row_size;
230	  }
231	
232	  PrimExpr HandleAccessPtrAndOffset(PrimExpr access_ptr,
233	                                    Optional<PrimExpr> offset = NullOpt,
234	                                    DataType dtype = DataType::Int(32)) {
235	    // The 2th arg of T.tvm_access_ptr call is offset, we set it to 0 and
236	    // accumulate it to smem_offset
237	    CHECK(access_ptr->IsInstance<CallNode>())
238	        << "Invalid access ptr for permuted layout: " << access_ptr;
239	    auto access_ptr_call = Downcast<Call>(access_ptr);
240	    if (access_ptr_call->op.same_as(builtin::tvm_access_ptr())) {
241	      LOG(FATAL) << "Transformation for tvm_access_ptr is not implemented yet";
242	    } else if (access_ptr_call->op.same_as(builtin::address_of())) {
243	      BufferLoad load = Downcast<BufferLoad>(access_ptr_call->args[0]);
244	      Array<PrimExpr> indices = load->indices;
245	      Array<PrimExpr> shape = load->buffer->shape;
246	
247	      CHECK_EQ(indices.size(), shape.size())
248	          << "Indices size and shape size must match for general N-dimensional "
249	             "buffer "
250	          << "but got indices size: " << indices.size()
251	          << " and shape size: " << shape.size();
252	
253	      PrimExpr elem_offset = 0;
254	      PrimExpr stride = 1;
255	
256	      for (int i = static_cast<int>(shape.size()) - 1; i >= 0; --i) {
257	        elem_offset += indices[i] * stride;
258	        stride *= shape[i];
259	      }
260	
261	      PrimExpr smem_offset =
262	          elem_offset + (offset.defined() ? offset.value() : 0);
263	
264	      auto new_buffer = buffer_remap_[load->buffer];
265	
266	      auto buffer_map_iter =
267	          buffer_map_.find(Downcast<Var>(load->buffer->data));
268	      CHECK(buffer_map_iter != buffer_map_.end())
269	          << "The buffer corresponding to data Var " << access_ptr_call->args[0]
270	          << " is not found";
271	
272	      int buffer_row_size = CheckAndGetBufferRowSize(buffer_map_iter->second);
273	      (void)buffer_row_size;
274	
275	      // Convert offset to target-dimension, reindex it and convert it back
276	      Array<PrimExpr> multi_dim_indices;
277	      PrimExpr remaining_offset = smem_offset;
278	
279	      for (int i = static_cast<int>(shape.size()) - 1; i >= 0; --i) {
280	        multi_dim_indices.insert(multi_dim_indices.begin(),
281	                                 floormod(remaining_offset, shape[i]));
282	        remaining_offset = floordiv(remaining_offset, shape[i]);
283	      }
284	
285	      auto forward_indices =
286	          layout_map_[load->buffer]->Forward(multi_dim_indices);
287	      PrimExpr new_offset = 0;
288	      PrimExpr stride_offset = 1;
289	      for (int i = static_cast<int>(shape.size()) - 1; i >= 0; --i) {
290	        new_offset += forward_indices[i] * stride_offset;
291	        stride_offset *= shape[i];
292	      }
293	      new_offset = analyzer_->Simplify(new_offset);
294	
295	      Array<PrimExpr> new_indices;
296	      for (int i = static_cast<int>(shape.size()) - 1; i >= 0; --i) {
297	        new_indices.insert(new_indices.begin(), floormod(new_offset, shape[i]));
298	        new_offset = floordiv(new_offset, shape[i]);
299	      }
300	
301	      auto new_access_ptr = access_ptr_call.CopyOnWrite();
302	      new_access_ptr->args.Set(0, BufferLoad(new_buffer, new_indices));
303	    } else {
304	      LOG(FATAL) << "Invalid access op for permuted layout: " << access_ptr;
305	    }
306	
307	    return access_ptr_call;
308	  }
309	
310	  PrimExpr VisitExpr_(const tir::CallNode *op) final {
311	    Array<RelayExpr> ptx_instructions = {builtin::ptx_ldmatrix(),
312	                                         builtin::mma_store()};
313	
314	    if (std::find(ptx_instructions.begin(), ptx_instructions.end(), op->op) ==
315	        ptx_instructions.end()) {
316	      auto call = Downcast<Call>(IRMutatorWithAnalyzer::VisitExpr_(op));
317	      return call;
318	    } else {
319	      is_ptx_ = true;
320	    }
321	    // Rewrite from/to shared or shared.ub/shared.l1 to/from local
322	    auto call = Downcast<Call>(IRMutatorWithAnalyzer::VisitExpr_(op));
323	    if (call->op.same_as(builtin::ptx_ldmatrix())) {
324	      // form: T.ptx_ldmatrix(..., smem_ptr, smem_offset)
325	      // smem_ptr: T.tvm_access_ptr(ptype, data, offset, extent, rw_mask)
326	      // or T.address_of(buffer, offset)
327	      auto access_ptr = call->args[5];
328	      PrimExpr smem_offset = call->args[6];
329	      Call address_of_call = Downcast<Call>(access_ptr);
330	      if (!address_of_call->op.same_as(builtin::address_of())) {
331	        LOG(FATAL) << "Invalid access ptr for permuted layout: " << access_ptr;
332	      }
333	      BufferLoad load = Downcast<BufferLoad>(address_of_call->args[0]);
334	
335	      if (buffer_remap_.count(load->buffer)) {
336	        auto new_access_ptr =
337	            HandleAccessPtrAndOffset(access_ptr, smem_offset, call->dtype);
338	        auto new_call = call.CopyOnWrite();
339	        new_call->args.Set(5, new_access_ptr);
340	        new_call->args.Set(6, IntImm(smem_offset->dtype, 0));
341	      }
342	    } else if (call->op.same_as(builtin::mma_store())) {
343	      // because we will directly store result to Buffer instead of calling
344	      // mma_store now
345	      auto access_ptr = call->args[2];
346	      auto new_access_ptr =
347	          HandleAccessPtrAndOffset(access_ptr, NullOpt, call->dtype);
348	      auto new_call = call.CopyOnWrite();
349	      new_call->args.Set(2, new_access_ptr);
350	    } else {
351	      LOG(FATAL) << "Invalid call node: " << call;
352	    }
353	    is_ptx_ = false;
354	    return call;
355	  }
356	
357	  PrimExpr VisitExpr_(const BufferLoadNode *op) final {
358	    auto load = Downcast<BufferLoad>(IRMutatorWithAnalyzer::VisitExpr_(op));
359	    if (is_ptx_) {
360	      return load;
361	    }
362	    auto buffer = load->buffer;
363	    if (buffer_remap_.count(buffer)) {
364	      auto new_indices = layout_map_[buffer]->Forward(load->indices);
365	      auto new_buffer = buffer_remap_[load->buffer];
366	      return BufferLoad(new_buffer, new_indices);
367	    } else if (var_remap_.count(buffer->data)) {
368	      auto new_buffer = Buffer(
369	          var_remap_[buffer->data], buffer->dtype, buffer->shape,
370	          buffer->strides, buffer->elem_offset, buffer->name,
371	          buffer->data_alignment, buffer->offset_factor, buffer->buffer_type);
372	      return BufferLoad(new_buffer, load->indices);
373	    }
374	    return load;
375	  }
376	
377	  Stmt VisitStmt_(const BufferStoreNode *op) final {
378	    auto store = Downcast<BufferStore>(IRMutatorWithAnalyzer::VisitStmt_(op));
379	    auto buffer = store->buffer;
380	    if (buffer_remap_.count(buffer)) {
381	      auto new_indices = layout_map_[buffer]->Forward(store->indices);
382	      auto new_buffer = buffer_remap_[store->buffer];
383	      return BufferStore(new_buffer, store->value, new_indices);
384	    } else if (var_remap_.count(buffer->data)) {
385	      auto new_buffer = Buffer(
386	          var_remap_[buffer->data], buffer->dtype, buffer->shape,
387	          buffer->strides, buffer->elem_offset, buffer->name,
388	          buffer->data_alignment, buffer->offset_factor, buffer->buffer_type);
389	      return BufferStore(new_buffer, store->value, store->indices);
390	    }
391	    return store;
392	  }
393	
394	  PrimExpr VisitExpr_(const VarNode *op) final {
395	    auto var = Downcast<Var>(IRMutatorWithAnalyzer::VisitExpr_(op));
396	    if (buffer_data_to_buffer_.count(var)) {
397	      auto buffer = buffer_data_to_buffer_[var];
398	      if (buffer_remap_.count(buffer))
399	        return buffer_remap_[buffer]->data;
400	    }
401	    return var;
402	  }
403	
404	  Stmt VisitStmt_(const EvaluateNode *op) final {
405	    const CallNode *call = op->value.as<CallNode>();
406	    // Do not analysis the call node to the global function.
407	    if (call && call->op.as<GlobalVarNode>())
408	      return Downcast<Evaluate>(IRMutatorWithAnalyzer::VisitStmt_(op));
409	
410	    auto tile_op = ParseOperator(GetRef<Stmt>(op), buffer_data_to_buffer_);
411	    if (tile_op == nullptr)
412	      return IRMutatorWithAnalyzer::VisitStmt_(op);
413	    AddWorkspaceCallback callback = [this](int num_elem, DataType dtype) {
414	      auto workspace =
415	          decl_buffer({PrimExpr(num_elem)}, dtype, "workspace", "shared");
416	      workspaces_.push_back(workspace);
417	      return workspace.access_ptr(2); // write
418	    };
419	
420	    // Get pass config `tl.disable_tma_lower`
421	    tvm::transform::PassContext ctxt = tvm::transform::PassContext::Current();
422	    Optional<Bool> opt_disable_tma_lower =
423	        ctxt->GetConfig(kDisableTMALower, Optional<Bool>());
424	    bool disable_tma_lower = opt_disable_tma_lower.value_or(Bool(false));
425	    Range thread_bounds;
426	
427	    if (analyzer_->const_int_bound.IsBound(thread_var_->var)) {
428	      auto const_int_bound = analyzer_->const_int_bound(thread_var_);
429	      auto min_value = const_int_bound->min_value;
430	      auto max_value = const_int_bound->max_value;
431	      auto extent = max_value + 1 - min_value;
432	      thread_bounds =
433	          Range::FromMinExtent(IntImm(thread_var_->var.dtype(), min_value),
434	                               IntImm(thread_var_->var.dtype(), extent));
435	    } else {
436	      thread_bounds = Range::FromMinExtent(0, 1);
437	    }
438	
439	    auto lowered =
440	        tile_op->Lower(LowerArgs{target_, thread_bounds, thread_var_->var,
441	                                 callback, layout_map_, buffer_remap_,
442	                                 disable_tma_lower, resource_scope_},
443	                       analyzer_);
444	    return IRMutatorWithAnalyzer::VisitStmt(lowered);
445	  }
446	
447	  Stmt VisitStmt_(const AttrStmtNode *op) final {
448	    if (op->attr_key == tir::attr::thread_extent) {
449	      IterVar iv = Downcast<IterVar>(op->node);
450	      ICHECK_NE(iv->thread_tag.length(), 0U);
451	      if (iv->thread_tag == "threadIdx.x") {
452	        thread_var_ = iv;
453	        ICHECK(iv->dom->extent.as<IntImmNode>());
454	        thread_block_size_ = iv->dom->extent.as<IntImmNode>()->value;
455	      }
456	    } else if (op->attr_key == "resource_scope") {
457	      resource_scope_ = Downcast<IntImm>(op->value)->value;
458	    }
459	    return arith::IRMutatorWithAnalyzer::VisitStmt_(op);
460	  }
461	
462	  Target target_;
463	  Map<Var, Buffer> buffer_data_to_buffer_;
464	  Map<Buffer, Layout> layout_map_;
465	  Map<Buffer, Buffer> buffer_remap_;
466	  // This is a workaround for cpu backend,
467	  // we need to define a thread_var for the serial loop.
468	  IterVar thread_var_ = IterVar(Range::FromMinExtent(0, 1), Var("v_thread"),
469	                                IterVarType::kDataPar);
470	  size_t thread_block_size_ = 0;
471	  Array<Buffer> workspaces_;
472	  // For ptx Node, we need to remap the buffer and indices
473	  // By access CallNode instead of BufferLoad Node.
474	  bool is_ptx_{false};
475	  // Mapping from data Var of a Buffer to Buffer, for lookup
476	  std::unordered_map<Var, Buffer, ObjectPtrHash, ObjectPtrEqual> buffer_map_;
477	  Map<Var, Var> var_remap_;
478	  int resource_scope_ = 0;
479	};
480	
481	namespace transform {
482	
483	using namespace tir::transform;
484	
485	tvm::transform::Pass LowerTileOp() {
486	  auto pass_func = [=](PrimFunc f, IRModule m, PassContext ctx) {
487	    return LowerTileOpPass::Substitute(std::move(f));
488	  };
489	  return CreatePrimFuncPass(pass_func, 0, "tl.LowerTileOp", {});
490	}
491	
492	TVM_REGISTER_GLOBAL("tl.transform.LowerTileOp").set_body_typed(LowerTileOp);
493	} // namespace transform
494	
495	} // namespace tl
496	} // namespace tvm
