57	/*! \brief Map a plain binary tl op to its AscendC op tag, or "" if not one. */
58	std::string BinaryTag(const CallNode *call) {
59	  if (call->op.same_as(ascend_add()))
60	    return "Add";
61	  if (call->op.same_as(ascend_sub()))
62	    return "Sub";
63	  if (call->op.same_as(ascend_mul()))
64	    return "Mul";
65	  if (call->op.same_as(ascend_div()))
