122	class AscendTailMaskPropagator : public arith::IRMutatorWithAnalyzer {
123	public:
124	  static PrimFunc Substitute(PrimFunc f, bool rewrite_reduce) {
125	    arith::Analyzer analyzer;
126	    AscendTailMaskPropagator m(&analyzer, rewrite_reduce);
127	    f.CopyOnWrite()->body = m.VisitStmt(f->body);
128	    return f;
129	  }
130	
131	  AscendTailMaskPropagator(arith::Analyzer *analyzer, bool rewrite_reduce)
132	      : arith::IRMutatorWithAnalyzer(analyzer),
133	        rewrite_reduce_(rewrite_reduce) {}
134	
135	private:
136	  // Per UB data Var -> current valid region. Absent => full (untracked).
137	  std::unordered_map<const VarNode *, TailMaskInfo> state_;
138	  // Whether reduce ops may be rewritten to tail_reduce. Disabled for the PTO
139	  // backend, whose reduce codegen handles valid shapes natively.
140	  bool rewrite_reduce_ = true;
141	
142	  // --- loop-variable scope tracking ---------------------------------------
143	  // A valid_row/valid_col expression seeded inside a loop may reference the
144	  // loop variable (e.g. copy_gm_to_ub in `for by` sets valid_col = f(by)).  If
145	  // a downstream op (e.g. reduce) runs *outside* that loop, emitting the
146	  // expression verbatim produces an undeclared-identifier compile error.  We
147	  // track all loop vars ever entered (all_loop_vars_) and those currently in
148	  // scope (active_loop_vars_); an expression referencing a loop var that is no
149	  // longer in scope is "out of scope" and the rewrite must bail.
150	  std::unordered_set<const VarNode *> all_loop_vars_;
151	  std::unordered_set<const VarNode *> active_loop_vars_;
152	
153	  bool HasOutOfScopeLoopVar(const PrimExpr &e) const {
154	    bool found = false;
155	    PostOrderVisit(e, [&](const ObjectRef &n) {
156	      if (const auto *v = n.as<VarNode>()) {
157	        if (all_loop_vars_.count(v) && !active_loop_vars_.count(v))
158	          found = true;
159	      }
160	    });
161	    return found;
162	  }
163	
164	  // --- conservative guards -------------------------------------------------
165	  // Only float-like dtypes have validated tail helpers; int/uint stay on the
166	  // full-tile path to avoid unsupported AscendC intrinsic instantiations.
167	  static bool SupportedTailDtype(DataType dt) {
168	    return dt.is_float() || dt.is_bfloat16();
169	  }
170	  // Element dtype behind an access_ptr (mirrors GetAccessPtrDtype in codegen).
171	  static DataType PtrDtype(const PrimExpr &e) {
172	    const auto *ap = e.as<CallNode>();
173	    if (ap == nullptr || ap->args.empty())
174	      return DataType::Handle();
175	    if (const auto *c = ap->args[0].as<CallNode>())
176	      return c->dtype;
177	    return DataType::Handle();
178	  }
179	  // Element count (extent) behind an access_ptr.
180	  static PrimExpr PtrExtent(const PrimExpr &e) {
181	    if (const auto *ap = e.as<CallNode>())
182	      if (ap->op.same_as(builtin::tvm_access_ptr()) && ap->args.size() >= 4)
183	        return ap->args[3];
184	    return PrimExpr();
185	  }
186	  // The 2D tail model only holds when the op's element count equals the
187	  // physical tile (physical_row * physical_col). For 3D / mismatched tiles the
188	  // rewrite would compute the wrong region, so we bail to the full-tile path.
189	  bool CleanTail(const PrimExpr &count, const TailMaskInfo &m) {
190	    return m.is_tail() && m.physical_row.defined() &&
191	           m.physical_col.defined() && count.defined() &&
192	           analyzer_->CanProveEqual(count, m.physical_row * m.physical_col);
193	  }
194	
195	  // Detect a broadcast-scalar tail mask: valid_col is a compile-time constant 1
196	  // while physical_col > 1. This happens when a 1D scalar (e.g. a per-channel
197	  // scale[bn]) is copied into a multi-element UB tile whose downstream op
198	  // broadcasts it across the full physical width. The valid_col=1 is correct
199	  // for the *copy* (only one scalar element exists), but rewriting the
200	  // downstream op to a tail helper with valid_col=1 would compute only one
201	  // element instead of the full broadcast -- so bail and let the full-tile path
202	  // (which reads the pad-filled gap) handle it.
203	  bool IsBroadcastScalarMask(const TailMaskInfo &m) const {
204	    if (!m.physical_col.defined())
205	      return false;
206	    auto *pcol = m.physical_col.as<IntImmNode>();
207	    if (pcol == nullptr || pcol->value <= 1)
208	      return false;
209	    // valid_col may be a Min(...) expr; use the analyzer to prove it equals 1.
210	    if (!m.valid_col.defined())
211	      return false;
212	    if (analyzer_->CanProveEqual(m.valid_col, 1))
213	      return true;
214	    return false;
215	  }
216	
217	  TailMaskInfo GetMask(const VarNode *v) const {
218	    if (v == nullptr)
219	      return TailMaskInfo{};
220	    auto it = state_.find(v);
221	    return it == state_.end() ? TailMaskInfo{} : it->second;
222	  }
223	
224	  Stmt VisitStmt_(const EvaluateNode *op) final {
225	    const auto *call = op->value.as<CallNode>();
226	    if (call == nullptr)
227	      return arith::IRMutatorWithAnalyzer::VisitStmt_(op);
228	
229	    // --- GM->UB copy: seed the destination's valid region. -----------------
230	    std::string ext = ExternName(call);
231	    if (ext.find("copy_gm_to_ub") != std::string::npos) {
232	      HandleGmToUbCopy(call);
233	      return GetRef<Stmt>(op);
234	    }
235	    // --- UB->UB copy: inherit the source's valid region. -------------------
236	    if (ext.find("copy_ub_to_ub") != std::string::npos) {
237	      if (call->args.size() >= 3) {
238	        const VarNode *src_v = GetPtrVar(call->args[1]);
239	        const VarNode *dst_v = GetPtrVar(call->args[2]);
240	        if (dst_v != nullptr)
241	          state_[dst_v] = GetMask(src_v);
242	      }
243	      return GetRef<Stmt>(op);
244	    }
245	    // copy_ub_to_gm and other copies are sinks: nothing to propagate.
246	    if (ext.find("copy_") != std::string::npos)
247	      return GetRef<Stmt>(op);
248	
249	    // --- Vector ops. -------------------------------------------------------
250	    if (Stmt rewritten = TryRewriteVectorOp(call); rewritten.defined())
251	      return rewritten;
252	
253	    return GetRef<Stmt>(op);
254	  }
255	
256	  Stmt VisitStmt_(const ForNode *op) final {
257	    all_loop_vars_.insert(op->loop_var.get());
258	    active_loop_vars_.insert(op->loop_var.get());
259	    Stmt s = arith::IRMutatorWithAnalyzer::VisitStmt_(op);
260	    active_loop_vars_.erase(op->loop_var.get());
261	    return s;
262	  }
263	
264	  void HandleGmToUbCopy(const CallNode *call) {
265	    // args: name(0) src_ptr(1) dst_ptr(2) strideN(3) validRow(4) validCol(5)
266	    //       pad_val(6) [physRow(7) physCol(8)]   (physRow omitted for 1D tiles;
267	    //       pad_val is always present in the hybrid scheme)
268	    if (call->args.size() < 7)
269	      return;
270	    const VarNode *dst_v = GetPtrVar(call->args[2]);
271	    if (dst_v == nullptr)
272	      return;
273	    PrimExpr valid_row = call->args[4];
274	    PrimExpr valid_col = call->args[5];
275	    PrimExpr phys_row, phys_col;
276	    if (call->args.size() >= 9) {
277	      phys_row = call->args[7];
278	      phys_col = call->args[8];
279	    } else if (call->args.size() == 8) {
280	      phys_row = IntImm(DataType::Int(32), 1);
281	      phys_col = call->args[7];
282	    } else {
283	      return;
284	    }
285	    state_[dst_v] =
286	        MakeCopyMask(valid_row, valid_col, phys_row, phys_col, analyzer_);
287	  }
288	
289	  // Returns a rewritten Stmt, or an undefined Stmt to keep the original.
290	  Stmt TryRewriteVectorOp(const CallNode *call) {
291	    // Binary: dst(0) src0(1) src1(2) count(3)
292	    if (std::string tag = BinaryTag(call); !tag.empty())
293	      return RewriteBinary(call, tag);
294	    // Unary: dst(0) src(1) count(2)
295	    if (std::string tag = UnaryTag(call); !tag.empty())
296	      return RewriteUnary(call, tag);
297	    // Scalar (immediate): dst(0) src(1) scalar(2) count(3)
298	    if (std::string tag = ScalarTag(call); !tag.empty())
299	      return RewriteScalar(call, tag);
300	    // Reduce: name(0) out(1) src(2) tmp(3) clear(4)
301	    if (call->op.same_as(ascend_reduce()))
302	      return RewriteReduce(call);
303	    // Cast: dst(0) src(1) roundmode(2) count(3) -- propagate only.
304	    if (call->op.same_as(ascend_cast())) {
305	      PropagateUnaryShape(call->args[0], call->args[1]);
306	      return Stmt();
307	    }
308	    // Broadcast: name(0) dst(1) src(2) tmp(3) dim(4) dstShape... srcShape...
309	    if (call->op.same_as(ascend_broadcast())) {
310	      PropagateBroadcast(call);
311	      return Stmt();
312	    }
313	    return Stmt();
314	  }
315	
316	  // dst inherits src's rectangle (used for cast / unrewritten unary shapes).
317	  void PropagateUnaryShape(const PrimExpr &dst_ptr, const PrimExpr &src_ptr) {
318	    const VarNode *dst_v = GetPtrVar(dst_ptr);
319	    if (dst_v != nullptr)
320	      state_[dst_v] = GetMask(GetPtrVar(src_ptr));
321	  }
322	
323	  Stmt RewriteUnary(const CallNode *call, const std::string &tag) {
324	    if (call->args.size() < 3)
325	      return Stmt();
326	    const VarNode *dst_v = GetPtrVar(call->args[0]);
327	    TailMaskInfo in = GetMask(GetPtrVar(call->args[1]));
328	    bool ok = CleanTail(call->args[2], in) &&
329	              SupportedTailDtype(PtrDtype(call->args[0])) &&
330	              !HasOutOfScopeLoopVar(in.valid_row) &&
331	              !HasOutOfScopeLoopVar(in.valid_col) && !IsBroadcastScalarMask(in);
332	    if (dst_v != nullptr)
333	      state_[dst_v] = ok ? in : TailMaskInfo{};
334	    if (!ok)
335	      return Stmt();
336	    Array<PrimExpr> a = {StringImm(tag), call->args[0], call->args[1],
337	                         in.valid_row,   in.valid_col,  in.physical_col};
338	    return Evaluate(Call(DataType::Handle(), ascend_tail_unary(), a));
339	  }
340	
341	  Stmt RewriteBinary(const CallNode *call, const std::string &tag) {
342	    if (call->args.size() < 4)
343	      return Stmt();
344	    const VarNode *dst_v = GetPtrVar(call->args[0]);
345	    TailMaskInfo lhs = GetMask(GetPtrVar(call->args[1]));
346	    TailMaskInfo rhs = GetMask(GetPtrVar(call->args[2]));
347	    TailMaskInfo out = IntersectMasks(lhs, rhs, analyzer_);
348	    bool ok = CleanTail(call->args[3], out) &&
349	              SupportedTailDtype(PtrDtype(call->args[0])) &&
350	              !HasOutOfScopeLoopVar(out.valid_row) &&
351	              !HasOutOfScopeLoopVar(out.valid_col) &&
352	              !IsBroadcastScalarMask(out);
353	    if (dst_v != nullptr)
354	      state_[dst_v] = ok ? out : TailMaskInfo{};
355	    if (!ok)
356	      return Stmt();
357	    Array<PrimExpr> a = {StringImm(tag),  call->args[0], call->args[1],
358	                         call->args[2],   out.valid_row, out.valid_col,
359	                         out.physical_col};
360	    return Evaluate(Call(DataType::Handle(), ascend_tail_binary(), a));
361	  }
362	
363	  Stmt RewriteScalar(const CallNode *call, const std::string &tag) {
364	    if (call->args.size() < 4)
365	      return Stmt();
366	    // Only the immediate-scalar form (args[2] is a scalar expr, not a pointer)
367	    // is rewritten; the "load scalar from buffer" form keeps the full path.
368	    if (GetPtrVar(call->args[2]) != nullptr)
369	      return Stmt();
370	    const VarNode *dst_v = GetPtrVar(call->args[0]);
371	    TailMaskInfo in = GetMask(GetPtrVar(call->args[1]));
372	    bool ok = CleanTail(call->args[3], in) &&
373	              SupportedTailDtype(PtrDtype(call->args[0])) &&
374	              !HasOutOfScopeLoopVar(in.valid_row) &&
375	              !HasOutOfScopeLoopVar(in.valid_col) && !IsBroadcastScalarMask(in);
376	    if (dst_v != nullptr)
377	      state_[dst_v] = ok ? in : TailMaskInfo{};
378	    if (!ok)
379	      return Stmt();
380	    Array<PrimExpr> a = {StringImm(tag), call->args[0], call->args[1],
381	                         call->args[2],  in.valid_row,  in.valid_col,
382	                         in.physical_col};
383	    return Evaluate(Call(DataType::Handle(), ascend_tail_scalar(), a));
384	  }
385	
386	  Stmt RewriteReduce(const CallNode *call) {
387	    // name(0) out(1) src(2) tmp(3) clear(4)
388	    if (call->args.size() < 5)
389	      return Stmt();
390	    const auto *name = call->args[0].as<StringImmNode>();
391	    if (name == nullptr)
392	      return Stmt();
393	    std::string reduce_tag = name->value; // e.g. reduce_sum<...>
394	    std::string kind = reduce_tag.substr(0, reduce_tag.find('<')); // reduce_sum
395	    int raw_dim = ParseReduceDim(reduce_tag);
396	    // Normalize to 0 (reduce rows) or -1 (reduce last axis). For 2D tiles
397	    // axis 0/-2 reduce rows and axis 1/-1 reduce columns.
398	    int dim = (raw_dim == 0 || raw_dim == -2) ? 0 : -1;
399	
400	    const VarNode *out_v = GetPtrVar(call->args[1]);
401	    TailMaskInfo in = GetMask(GetPtrVar(call->args[2]));
402	
403	    // Reduce is rewritten to a valid-region tail_reduce (which needs no pad)
404	    // only on the AscendC backend, for a clean 2D float tile. On PTO, or for
405	    // 3D / int tiles, it stays the native reduce over the pad-filled tile.
406	    // The valid_row/valid_col must also not reference loop vars that have
407	    // already gone out of scope (e.g. a copy seeded inside `for by` whose
408	    // valid_col = f(by), but the reduce runs outside the loop).
409	    bool ok = rewrite_reduce_ && CleanTail(PtrExtent(call->args[2]), in) &&
410	              SupportedTailDtype(PtrDtype(call->args[2])) &&
411	              !HasOutOfScopeLoopVar(in.valid_row) &&
412	              !HasOutOfScopeLoopVar(in.valid_col) && !IsBroadcastScalarMask(in);
413	
414	    // Output rectangle for downstream propagation (only when rewriting).
415	    TailMaskInfo out;
416	    if (ok) {
417	      out.kind = TailMaskKind::kTail;
418	      if (dim == 0) {
419	        out.valid_row = IntImm(DataType::Int(32), 1);
420	        out.valid_col = in.valid_col;
421	        out.physical_row = IntImm(DataType::Int(32), 1);
422	        out.physical_col = in.physical_col;
423	      } else { // dim == -1 (reduce last axis) -> column vector
424	        out.valid_row = in.valid_row;
425	        out.valid_col = IntImm(DataType::Int(32), 1);
426	        out.physical_row = in.physical_row;
427	        out.physical_col = IntImm(DataType::Int(32), 1);
428	      }
429	      out.storage_col = out.physical_col;
430	    }
431	    if (out_v != nullptr)
432	      state_[out_v] = out;
433	
434	    if (!ok)
435	      return Stmt();
436	
437	    // tail_reduce: kind(0) out(1) src(2) tmp(3) dim(4)
438	    //              valid_row(5) valid_col(6) phys_col(7) clear(8)
439	    Array<PrimExpr> a = {StringImm(kind),
440	                         call->args[1],
441	                         call->args[2],
442	                         call->args[3],
443	                         IntImm(DataType::Int(32), dim),
444	                         in.valid_row,
445	                         in.valid_col,
446	                         in.physical_col,
447	                         call->args[4]};
448	    return Evaluate(Call(DataType::Handle(), ascend_tail_reduce(), a));
449	  }
450	
451	  void PropagateBroadcast(const CallNode *call) {
452	    // name(0) dst(1) src(2) tmp(3) dim(4) dstShape[dim] srcShape[dim]
453	    if (call->args.size() < 5)
454	      return;
455	    const VarNode *dst_v = GetPtrVar(call->args[1]);
456	    if (dst_v == nullptr)
457	      return;
458	    TailMaskInfo in = GetMask(GetPtrVar(call->args[2]));
459	    const auto *dim_imm = call->args[4].as<IntImmNode>();
460	    if (!in.is_tail() || dim_imm == nullptr || dim_imm->value != 2) {
461	      state_[dst_v] = in; // 1D / untracked: pass through
462	      return;
463	    }
464	    // 2D broadcast. dstShape = args[5],args[6]; srcShape = args[7],args[8].
465	    if (call->args.size() < 9) {
466	      state_[dst_v] = in;
467	      return;
468	    }
469	    PrimExpr dst_rows = call->args[5];
470	    PrimExpr dst_cols = call->args[6];
471	    PrimExpr src_rows = call->args[7];
472	    PrimExpr src_cols = call->args[8];
473	    TailMaskInfo out;
474	    out.kind = TailMaskKind::kTail;
475	    out.physical_row = dst_rows;
476	    out.physical_col = dst_cols;
477	    out.storage_col = dst_cols;
478	    if (is_one(src_cols)) {
479	      // [M,1] -> [M,N]: row tail carries, all columns become valid.
480	      out.valid_row = in.valid_row;
481	      out.valid_col = dst_cols;
482	    } else if (is_one(src_rows)) {
483	      // [1,N] -> [M,N]: column tail carries, all rows become valid.
484	      out.valid_row = dst_rows;
485	      out.valid_col = in.valid_col;
486	    } else {
487	      out = in;
488	    }
489	    state_[dst_v] = out;
490	  }
491	
492	  static int ParseReduceDim(const std::string &tag) {
493	    // tag like "reduce_sum<float, 16, 32, -1>"; dim is the last template field.
494	    size_t lt = tag.find('<');
495	    size_t gt = tag.rfind('>');
496	    if (lt == std::string::npos || gt == std::string::npos || gt <= lt)
497	      return -1;
498	    std::string inner = tag.substr(lt + 1, gt - lt - 1);
499	    size_t comma = inner.rfind(',');
500	    std::string dim_str =
501	        comma == std::string::npos ? inner : inner.substr(comma + 1);
502	    try {
503	      return std::stoi(dim_str);
504	    } catch (...) {
505	      return -1;
506	    }
507	  }
508	};
509	
510	// Opt-in switch for the tail-block valid-region scheme. Must be registered so
511	// PassContext accepts it as a config option (default off).
512	static constexpr const char *kAscendTailMask = "tl.ascend_tail_mask";
513	TVM_REGISTER_PASS_CONFIG_OPTION(kAscendTailMask, Bool);
514	
515	namespace transform {
516	
517	using namespace tir::transform;
518	
519	tvm::transform::Pass AscendTailMaskPropagation(bool rewrite_reduce) {
520	  auto pass_func = [=](PrimFunc f, IRModule m, PassContext ctx) {
521	    // Opt-in: the tail-block scheme is off unless TL_ASCEND_TAIL_MASK is set,
522	    // so non-tail kernels are left untouched.
523	    bool ascend_tail_mask =
524	        ctx->GetConfig<Bool>(kAscendTailMask, Bool(false)).value();
525	    if (!ascend_tail_mask) {
526	      return f;
527	    }
528	    return AscendTailMaskPropagator::Substitute(std::move(f), rewrite_reduce);
529	  };
530	  return CreatePrimFuncPass(pass_func, 0, "tl.AscendTailMaskPropagation", {});
531	}
532	
533	TVM_REGISTER_GLOBAL("tl.transform.AscendTailMaskPropagation")
534	    .set_body_typed(AscendTailMaskPropagation);
535	} // namespace transform
536	
537	} // namespace tl
538	} // namespace tvm
