113	      }
114	
115	      // We want to check if index < shape_dim can be proven.
116	      // If analyzer->CanProve(index < shape_dim) returns false,
117	      // it means we cannot prove the access is within bounds.
118	      PrimExpr upper_bound_cond = index < shape_dim;
119	      if (!analyzer_->CanProve(upper_bound_cond)) {
120	        _conditions.push_back(upper_bound_cond);
