34	  /*! \brief Whole physical tile is valid (statically full -> never rewritten).
35	   */
36	  kFull = 0,
37	  /*! \brief A regular 2D rectangle [valid_row, valid_col] inside the tile. */
38	  kTail = 1,
39	  /*! \brief Packed comparison mask (Batch 2: compare/select). */
40	  kPackedCmp = 2,
41	};
