43	/*!
44	 * \brief Logical valid region plus physical pitch of a UB tile.
45	 *
46	 *  - `valid_row` / `valid_col` describe the logically-valid rectangle. They may
47	 *    be dynamic (a `Select(...)` over the block index), which is exactly why
48	 * the rewrite produces a *runtime* tail helper instead of a compile-time shape.
49	 *  - `physical_row` / `physical_col` are the allocated UB tile dims;
50	 * `physical_col` is the row pitch used to derive repeat strides.
51	 *  - `storage_col` is reserved for packed comparison masks (Batch 2).
52	 */
53	struct TailMaskInfo {
54	  TailMaskKind kind = TailMaskKind::kFull;
55	  PrimExpr valid_row;
56	  PrimExpr valid_col;
57	  PrimExpr physical_row;
58	  PrimExpr physical_col;
59	  PrimExpr storage_col;
