64	/*! \brief A fully-valid mask for a tile of the given physical dims. */
65	inline TailMaskInfo MakeFullMask(PrimExpr physical_row, PrimExpr physical_col) {
66	  TailMaskInfo m;
67	  m.kind = TailMaskKind::kFull;
68	  m.valid_row = physical_row;
69	  m.valid_col = physical_col;
70	  m.physical_row = physical_row;
71	  m.physical_col = physical_col;
