78	 *        pair is statically a full tile. When both extents are constants equal
79	 *        to the physical dims the buffer is full and must NOT be rewritten, so
80	 *        non-tail kernels keep generating identical code.
81	 */
82	inline bool IsStaticallyFull(const PrimExpr &valid_row,
83	                             const PrimExpr &valid_col,
84	                             const PrimExpr &physical_row,
85	                             const PrimExpr &physical_col,
86	                             arith::Analyzer *analyzer) {
